                                                                                                                                                                                                             
  CREATE TABLE "TENANT_EVENT_REVIEW"                                                                                                                                                              
   (	"EVENT_REVIEW_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"EVENT_ID" NUMBER NOT NULL ENABLE,                                                                                                                                                                          
	"CREATED_TIME" DATE NOT NULL ENABLE,                                                                                                                                                                        
	"END_TIME" DATE NOT NULL ENABLE,                                                                                                                                                                            
	"AUDIT_STATE" VARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                                 
	"AUDIT_USER" NUMBER,                                                                                                                                                                                        
	"AUDIT_OPINION" NVARCHAR2(1000),                                                                                                                                                                            
	"MAIN_RESPONSIBLE_USER" NUMBER,                                                                                                                                                                             
	"ABNORMAL_ANALYSIS_USER" NUMBER,                                                                                                                                                                            
	"SECONDARY_USER" VARCHAR2(512),                                                                                                                                                                             
	"WHY5_ANALYSIS_CONTENT" NVARCHAR2(2000),                                                                                                                                                                    
	"WHY5_ANALYSIS_IMAGE" VARCHAR2(4000),                                                                                                                                                                       
	"ABNORMAL_PROBLEM_CONTENT" NVARCHAR2(2000),                                                                                                                                                                 
	"ABNORMAL_PROBLEM_IMAGE" VARCHAR2(4000),                                                                                                                                                                    
	"PROCESS_ANALYSIS_CONTENT" NVARCHAR2(2000),                                                                                                                                                                 
	"PROCESS_ANALYSIS_IMAGE" VARCHAR2(4000),                                                                                                                                                                    
	"IMPROVE_METHOD_CONTENT" NVARCHAR2(2000),                                                                                                                                                                   
	"IMPROVE_METHOD_IMAGE" VARCHAR2(4000),                                                                                                                                                                      
	"FUNCTION_NAME_CONTENT" NVARCHAR2(2000),                                                                                                                                                                    
	"FUNCTION_NAME_IMAGE" VARCHAR2(4000),                                                                                                                                                                       
	"DEVICE_KEY_CONTENT" NVARCHAR2(2000),                                                                                                                                                                       
	"DEVICE_KEY_IMAGE" VARCHAR2(4000),                                                                                                                                                                          
	"STRUCTURAL_PRINCIPLE_CONTENT" NVARCHAR2(2000),                                                                                                                                                             
	"STRUCTURAL_PRINCIPLE_IMAGE" VARCHAR2(4000),                                                                                                                                                                
	"DAILY_MAINTAIN_CONTENT" NVARCHAR2(2000),                                                                                                                                                                   
	"DAILY_MAINTAIN_IMAGE" VARCHAR2(4000),                                                                                                                                                                      
	"UPDATE_DATE" DATE DEFAULT SYSDATE,                                                                                                                                                                         
	"UPDATED_BY" NUMBER,                                                                                                                                                                                        
	"CREATION_DATE" DATE DEFAULT SYSDATE,                                                                                                                                                                       
	"CREATED_BY" NUMBER NOT NULL ENABLE,                                                                                                                                                                        
	"TENANT_ID" NUMBER DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                               
	"AUDIT_NAME" NVARCHAR2(600),                                                                                                                                                                                
	"PDF_URL" NVARCHAR2(256),                                                                                                                                                                                   
	"NOTICE_FLAG" NUMBER DEFAULT 0,                                                                                                                                                                             
	"AUDIT_TYPE" VARCHAR2(20),                                                                                                                                                                                  
	"TAGS" NVARCHAR2(2000),                                                                                                                                                                                     
	"AUDIT_TITLE" NVARCHAR2(600),                                                                                                                                                                               
	"PPT_URL" VARCHAR2(1000),                                                                                                                                                                                   
	"REMARK" NVARCHAR2(500),                                                                                                                                                                                    
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                               
	 CONSTRAINT "CHECK_NOTICE" CHECK (NOTICE_FLAG IN (1,0)) ENABLE,                                                                                                                                             
	 PRIMARY KEY ("EVENT_REVIEW_ID")                                                                                                                                                                            
  USING INDEX  ENABLE,                                                                                                                                                                                       
	 CHECK (AUDIT_STATE IN ('WAIT', 'COMPLETE', 'REJECT', 'AUDIT', 'UNREVIEW')) ENABLE                                                                                                                          
   ) ;                                                                                                                                                                                                       

